// _codecs_putParity writes the encoding of the Parity that x points at into the
// end of buf, which has room for it, and returns its length. It fails when x
// fails to encode itself.
func _codecs_putParity(buf []byte, x *Parity, loc string, num int) (int, error) {
	enc, err := x.MarshalBinary()
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	return copy(buf[len(buf)-len(enc):], enc), nil
}

